if (root == nullptr || child == nullptr || root == child) {
    return nullptr;
}

std::stack<Node*> stack;
stack.push(root);

while (!stack.empty()) {
    Node* current = stack.top();
    stack.pop();

    for (Node* node : current->children) {
        if (node == child) {
            return current;
        }
        stack.push(node);
    }
}

return nullptr;
// END_CODE

